    const shared = document.createElement("script"); shared.src = "comms.js?v=" + (window.B2B_VERSION || "1"); shared.onload = () => { const s = document.createElement("script"); s.src = "member.js?v=" + (window.B2B_VERSION || "1"); document.body.appendChild(s); }; shared.onerror = () => { gate.hidden = false; gate.textContent = "Could not load Player Passport. Please refresh."; }; document.body.appendChild(shared);
